const hash = msg.req.params.hash;

if (!/^[a-fA-F0-9]{64}$/.test(hash)) {
    msg.statusCode = 400;
    msg.payload = "Invalid SHA-256 hash";
    return [null, msg];
}

msg.hash = hash;
msg.tsqfile = `/tmp/request-${msg._msgid}.tsq`;
msg.tsrfile = `/tmp/request-${msg._msgid}.tsr`;
msg.payload = `ts -query -digest ${hash} -sha256 -cert -out ${msg.tsqfile}`;

return [msg, null];

// openssl reads and rewrites the serial file without a lock. Parallel replies
// then reuse serial numbers or are rejected ("Error during serial number
// generation.") with exit code 0, so one reply runs at a time.
msg.payload = `/data/tsa-state/serial.lock openssl ts -reply -queryfile ${msg.tsqfile} -config /data/tsa/openssl-tsa.cnf -out ${msg.tsrfile}`;
return msg;

if (msg.payload && msg.payload.code === 0) {
    msg.filename = msg.tsrfile;
    return [msg, null];
}
msg.statusCode = 502;
msg.payload = `local TSA reply failed rc=${msg.payload && msg.payload.code}`;
return [null, msg];

// RFC 3161 over HTTP POST (application/timestamp-query), the interface a
// timestamp client such as DSS uses. The body is the DER TimeStampReq; the
// reply comes from the same local TSA chain as GET /tsa/:hash.
// Node-RED hands over a body that is valid UTF-8 as a string, any other as a
// Buffer; both carry the same bytes.
const body = typeof msg.payload === "string" ? Buffer.from(msg.payload, "utf8") : msg.payload;
const type = String((msg.req && msg.req.headers && msg.req.headers["content-type"]) || "").split(";")[0].trim().toLowerCase();
if (type !== "application/timestamp-query") {
    msg.statusCode = 415;
    msg.payload = "Content-Type must be application/timestamp-query";
    return [null, msg];
}
// A TimeStampReq is a DER SEQUENCE of a few hundred bytes at most.
if (!Buffer.isBuffer(body) || body.length < 16 || body.length > 4096 || body[0] !== 0x30) {
    msg.statusCode = 400;
    msg.payload = "Body is not a DER TimeStampReq";
    return [null, msg];
}
msg.tsqfile = `/tmp/request-${msg._msgid}.tsq`;
msg.tsrfile = `/tmp/request-${msg._msgid}.tsr`;
fs.writeFileSync(msg.tsqfile, body);
msg.payload = `/data/tsa-state/serial.lock openssl ts -reply -queryfile ${msg.tsqfile} -config /data/tsa/openssl-tsa.cnf -out ${msg.tsrfile}`;
return [msg, null];
